// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {X_WALLET, Log} from "../src/X_WALLET.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    X_WALLET c;
    Log lg;
    function setUp() public { lg = new Log(); c = new X_WALLET(address(lg)); }
    function testFuzz_property(uint256 amount, address actor, uint256 unlockTime) public {
        vm.assume(amount <= VALUE_CAP);
        vm.assume(actor != address(0));
        amount = bound(amount, 1, 10 ether);
        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(unlockTime);
        // rule: any successful Put appends a History entry recording the deposit
        bool recorded = true;
        uint256 val;
        address sender;
        try lg.History(0) returns (address s, string memory, uint256 v, uint256) {
            sender = s;
            val = v;
        } catch {
            recorded = false;
        }
        assertTrue(recorded && sender == actor && val == amount);
    }
}
